def buyer_count(processes, suppliers=None):
    """Número de procesos por entidad compradora."""
    return processes.groupBy('buyer_id').agg(F.count('*').alias('value'))

RDD.code:
def buyer_count(processes, suppliers=None):
    """Número de procesos por entidad compradora: el clásico conteo de palabras."""
    return processes.select('buyer_id').rdd.map(lambda row: (row[0], 1)).reduceByKey(lambda a, b: a + b)
